-- GENERATED BY QueryOne AT 2021-03-04 14:17:53
-- USING SYSTEM@172.31.120.104:1531(OSGGDB2)

CREATE OR REPLACE FUNCTION ECAMS.CHGPATH
  (SYSCD  IN VARCHAR2,
   RSRCCD IN VARCHAR2,
   JOBCD  IN VARCHAR2,
   DIRPATH IN VARCHAR2)
RETURN VARCHAR2
IS
  VCNT INT := 0;
  HOMEPATH VARCHAR2(100);
  CHGPATH  VARCHAR2(200);


BEGIN
    HOMEPATH := NULL;

    SELECT COUNT(*)
      INTO VCNT
      FROM CMM0038 B,CMM0031 A
     WHERE A.CM_SYSCD=SYSCD
       AND A.CM_SVRCD='01'
       AND A.CM_CLOSEDT IS NULL
       AND A.CM_SYSCD=B.CM_SYSCD
       AND A.CM_SVRCD=B.CM_SVRCD
       AND A.CM_SEQNO=B.CM_SEQNO
       AND B.CM_RSRCCD=RSRCCD;
    IF VCNT = 1 THEN
        SELECT B.CM_VOLPATH
          INTO HOMEPATH
          FROM CMM0038 B,CMM0031 A
         WHERE A.CM_SYSCD=SYSCD
           AND A.CM_SVRCD='01'
           AND A.CM_CLOSEDT IS NULL
           AND A.CM_SYSCD=B.CM_SYSCD
           AND A.CM_SVRCD=B.CM_SVRCD
           AND A.CM_SEQNO=B.CM_SEQNO
           AND B.CM_RSRCCD=RSRCCD;
    ELSIF VCNT > 1 THEN
        SELECT B.CM_VOLPATH
          INTO HOMEPATH
          FROM CMM0038 B,CMM0031 A
         WHERE A.CM_SYSCD=SYSCD
           AND A.CM_SVRCD='01'
           AND A.CM_CLOSEDT IS NULL
           AND A.CM_SYSCD=B.CM_SYSCD
           AND A.CM_SVRCD=B.CM_SVRCD
           AND A.CM_SEQNO=B.CM_SEQNO
           AND B.CM_RSRCCD=RSRCCD
           AND NVL(A.CM_CMPSVR,'N')='Y'
           AND ROWNUM=1;
    END IF;
    IF HOMEPATH IS NULL THEN
       SELECT B.CM_VOLPATH
          INTO HOMEPATH
          FROM CMM0038 B,CMM0031 A
         WHERE A.CM_SYSCD=SYSCD
           AND A.CM_SVRCD='01'
           AND A.CM_CLOSEDT IS NULL
           AND A.CM_SYSCD=B.CM_SYSCD
           AND A.CM_SVRCD=B.CM_SVRCD
           AND A.CM_SEQNO=B.CM_SEQNO
           AND B.CM_RSRCCD=RSRCCD
           AND ROWNUM=1;
    END IF;

    IF HOMEPATH IS NULL THEN
       RETURN DIRPATH;
    END IF;

    IF SUBSTR(DIRPATH,1,LENGTH(HOMEPATH)) <> HOMEPATH THEN
       RETURN DIRPATH;
    END IF;

    IF LENGTH(HOMEPATH) >= LENGTH(DIRPATH) THEN
       RETURN HOMEPATH;
    END IF;

    CHGPATH := HOMEPATH || '/' || SUBSTR(JOBCD,4) || '/' || SUBSTR(JOBCD,1,3);
    IF SUBSTR(DIRPATH,1,LENGTH(CHGPATH)) = CHGPATH THEN
       IF LENGTH(DIRPATH) > LENGTH(CHGPATH) THEN
          CHGPATH := HOMEPATH || SUBSTR(DIRPATH,LENGTH(CHGPATH)+1);
       ELSE
          CHGPATH := HOMEPATH;
       END IF;
    END IF;
    RETURN CHGPATH;
END;